element.event:
local islandMode = game.player():getActiveIsland():islandMode()
local statsArray = (islandMode == 0) and { "template_stat_species", "template_stat_class", "template_stat_beds", "template_stat_paironormal_currency_rate", "template_stat_paironormal_max_currency", "template_stat_sellprice" } or -- islandMode 1 { "template_stat_species", "template_stat_class", "template_stat_beds", "template_stat_underlingrate", "template_stat_sellprice" }
element:populateStatsArr(statsArray)
